#!/usr/bin/env bash
# Produces the sources every platform builds from, and the spec that describes them.
#
#   prepare-source.sh <work-dir> [upstream-sha [overlay-sha]]
#
# Clones UPSTREAM_REPO, merges the generator overlay onto it, rebuilds the generators and regenerates
# the C bindings and opendaq.json. Nothing generated is ever merged: a conflict in a generated file is
# settled by regenerating it, and a conflict anywhere else fails the run, because it means the overlay
# branch needs a rebase by hand.
#
# Leaves in <work-dir>/out:
#   opendaq.json              the API spec
#   bindings-overlay.patch    everything that differs from the upstream commit (git apply --binary)
#   opendaq-c-headers.tar.gz  bindings/c/include
#   source-info.env           UPSTREAM_SHA / OVERLAY_SHA that were built
# and the prepared tree in <work-dir>/openDAQ.
set -euo pipefail

here="$(cd "$(dirname "$0")/.." && pwd)"
# shellcheck source=../nightly.env
. "$here/nightly.env"

work="${1:?usage: prepare-source.sh <work-dir> [upstream-sha [overlay-sha]]}"
mkdir -p "$work"
work="$(cd "$work" && pwd)"
src="$work/openDAQ"
out="$work/out"
rm -rf "$src" "$out"
mkdir -p "$out"

git clone --quiet --no-tags -c core.autocrlf=false "$UPSTREAM_REPO" "$src"
cd "$src"
git checkout --quiet --detach "${2:-origin/$UPSTREAM_REF}"
upstream_sha="$(git rev-parse HEAD)"
overlay_sha=""

if [ -n "${OVERLAY_REPO:-}" ]; then
    git fetch --quiet --no-tags "$OVERLAY_REPO" "$OVERLAY_REF"
    overlay_sha="$(git rev-parse "${3:-FETCH_HEAD}")"

    # A file may be regenerated rather than merged when the overlay's copy carries the generator
    # banner, or is one of the generator's own build products.
    regenerable() {
        case "$1" in
            bindings/json/opendaq.json) return 0 ;;
            shared/tools/RTGen/bin/RTGen.C.dll | shared/tools/RTGen/bin/RTGen.Json.dll) return 0 ;;
            shared/tools/RTGen/bin/Templates/c.* | shared/tools/RTGen/bin/Templates/json.*) return 0 ;;
        esac
        git show "$overlay_sha:$1" 2>/dev/null | head -n 3 | grep -q '<auto-generated>'
    }

    if ! git -c user.name=nightly -c user.email=nightly@localhost \
            merge --quiet --no-ff --no-commit "$overlay_sha" >"$out/merge.log" 2>&1; then
        unresolved=0
        while IFS= read -r path; do
            if regenerable "$path"; then
                git checkout --quiet --theirs -- "$path" 2>/dev/null || git rm --quiet --cached -- "$path"
                git add -- "$path" 2>/dev/null || true
            else
                echo "::error::merge conflict in hand-written file $path -- rebase $OVERLAY_REF onto $UPSTREAM_REF" >&2
                unresolved=1
            fi
        done < <(git diff --name-only --diff-filter=U)
        if [ "$unresolved" -ne 0 ]; then
            cat "$out/merge.log" >&2
            exit 1
        fi
    fi
fi

# Rebuilds RTGen.C.dll / RTGen.Json.dll from source and regenerates the C bindings and the spec.
bash bindings/regenerate.sh

# The spec and the C bindings must describe the same surface.
python3 bindings/json/check_c_bindings.py bindings/json/opendaq.json bindings/c/include

git add -A
git diff --cached --binary "$upstream_sha" > "$out/bindings-overlay.patch"
cp bindings/json/opendaq.json "$out/opendaq.json"
tar -czf "$out/opendaq-c-headers.tar.gz" -C bindings/c/include .
{
    echo "UPSTREAM_REPO=$UPSTREAM_REPO"
    echo "UPSTREAM_REF=$UPSTREAM_REF"
    echo "UPSTREAM_SHA=$upstream_sha"
    echo "OVERLAY_REPO=${OVERLAY_REPO:-}"
    echo "OVERLAY_REF=${OVERLAY_REF:-}"
    echo "OVERLAY_SHA=$overlay_sha"
} > "$out/source-info.env"

echo "prepared $src (upstream $upstream_sha, overlay ${overlay_sha:-none})"
ls -l "$out"
